/// A テーマ in the style settings, by the id that is saved.
public enum Theme: String, CaseIterable, Sendable {
  case pochical
  case zen
  case sumi
  case milktea
  case matcha
  case cocoa
  case soda
  case sakura
  case sumire
  case kissa
  case tsukiyo
  case kokuban

  public var name: String {
    switch self {
    case .pochical: "ポチカル"
    case .zen: "禅"
    case .sumi: "墨"
    case .milktea: "ミルクティー"
    case .matcha: "抹茶"
    case .cocoa: "ココア"
    case .soda: "ソーダ"
    case .sakura: "さくら"
    case .sumire: "すみれ"
    case .kissa: "喫茶"
    case .tsukiyo: "月夜"
    case .kokuban: "黒板"
    }
  }

  /// Drawn dark whatever 外観 says.
  public var isAlwaysDark: Bool {
    switch self {
    case .pochical: false
    case .zen: false
    case .sumi: false
    case .milktea: false
    case .matcha: false
    case .cocoa: false
    case .soda: false
    case .sakura: false
    case .sumire: false
    case .kissa: true
    case .tsukiyo: true
    case .kokuban: true
    }
  }

  public func colors(_ scheme: ColorScheme) -> ThemeColors {
    let dark = scheme == .dark
    return switch self {
    case .pochical: dark ? .pochicalDark : .pochicalLight
    case .zen: dark ? .zenDark : .zenLight
    case .sumi: dark ? .sumiDark : .sumiLight
    case .milktea: dark ? .milkteaDark : .milkteaLight
    case .matcha: dark ? .matchaDark : .matchaLight
    case .cocoa: dark ? .cocoaDark : .cocoaLight
    case .soda: dark ? .sodaDark : .sodaLight
    case .sakura: dark ? .sakuraDark : .sakuraLight
    case .sumire: dark ? .sumireDark : .sumireLight
    case .kissa: .kissaDark
    case .tsukiyo: .tsukiyoDark
    case .kokuban: .kokubanDark
    }
  }
}

